b_spouse = observation(entity='Charlie', entity_source='s20', predicate='spouse of the taxpayer', predicate_source='s4')
b_dependent = observation(entity='Bob', entity_source='s20', predicate='dependent of the taxpayer', predicate_source='s6')
b_joint_return = observation(entity='Alice', entity_source='s20', predicate='joint return', predicate_source='s4')
b_spouse_income = observation(entity='Charlie', entity_source='s20', predicate='has no gross income', predicate_source='s4')
b_spouse_dependent = observation(entity='Charlie', entity_source='s20', predicate='dependent of another taxpayer', predicate_source='s4')
b_tax_year = observation(entity='Alice', entity_source='s20', predicate='taxable year begins', predicate_source='s4')
b_exemption_amount = residual(source='s10', quote='the term \"exemption amount\" means $2,000')
b_exemption_disallowed = residual(source='s12', quote='the exemption amount applicable to such individual for such individual's taxable year shall be zero')
b_phaseout_applicable = residual(source='s15', quote='the exemption amount shall be reduced by the applicable percentage')
b_applicable_percentage = residual(source='s17', quote='the term \"applicable percentage\" means 2 percentage points for each $2,500 (or fraction thereof)')
b_special_rule = residual(source='s19', quote='the term \"exemption amount\" means zero')
@scope('s0') 
def allowance_of_deductions_scope(): 
    return True 
@scope('s1') 
def allowance_of_deductions_scope(): 
    return allowance_of_deductions_scope 
@scope('s2') 
def deduction_allowance_scope(): 
    return allowance_of_deductions_scope 
@scope('s3') 
def taxpayer_and_spouse_scope(): 
    return allowance_of_deductions_scope 
@scope('s4') 
def spouse_exemption_scope(): 
    return (taxpayer_and_spouse_scope and b_spouse and b_joint_return and b_spouse_income and (not b_spouse_dependent)) 
@scope('s5') 
def dependent_exemption_scope(): 
    return allowance_of_deductions_scope 
@scope('s6') 
def dependent_exemption_scope(): 
    return (dependent_exemption_scope and b_dependent) 
@scope('s7') 
def exemption_amount_scope(): 
    return allowance_of_deductions_scope 
@scope('s8') 
def exemption_amount_scope(): 
    return exemption_amount_scope 
@scope('s9') 
def exemption_amount_scope(): 
    return exemption_amount_scope 
@scope('s10') 
def exemption_amount_scope(): 
    return (exemption_amount_scope and b_exemption_amount) 
@scope('s11') 
def dependent_exemption_disallowed_scope(): 
    return (exemption_amount_scope and b_exemption_disallowed) 
@scope('s13') 
def phaseout_scope(): 
    return exemption_amount_scope 
@scope('s14') 
def phaseout_scope(): 
    return phaseout_scope 
@scope('s15') 
def phaseout_scope(): 
    return (phaseout_scope and b_phaseout_applicable) 
@scope('s16') 
def applicable_percentage_scope(): 
    return phaseout_scope 
@scope('s17') 
def applicable_percentage_scope(): 
    return (applicable_percentage_scope and b_applicable_percentage) 
@scope('s18') 
def special_rule_scope(): 
    return exemption_amount_scope 
@scope('s19') 
def exemption_amount_special_rule_scope(): 
    return (special_rule_scope and b_special_rule) 
@rule('s4', otherwise=False) 
def spouse_exemption_rule(): 
    return (spouse_exemption_scope and b_spouse and b_joint_return and b_spouse_income and (not b_spouse_dependent)) 
@rule('s6', otherwise=False) 
def dependent_exemption_rule(): 
    return (dependent_exemption_scope and b_dependent) 
@rule('s10', otherwise=False) 
def exemption_amount_rule(): 
    return (exemption_amount_scope and b_exemption_amount) 
@rule('s12', otherwise=False) 
def dependent_exemption_disallowed_rule(): 
    return (exemption_amount_scope and b_exemption_disallowed) 
@rule('s15', otherwise=False) 
def phaseout_rule(): 
    return (phaseout_scope and b_phaseout_applicable) 
@rule('s17', otherwise=False) 
def applicable_percentage_rule(): 
    return (applicable_percentage_scope and b_applicable_percentage) 
@rule('s19', otherwise=False) 
def exemption_amount_special_rule(): 
    return (special_rule_scope and b_special_rule) 
query = ('Entailment' if (spouse_exemption_rule or dependent_exemption_rule) else 'Contradiction')
